sys_script.script:
(function executeRule(current, previous /*null when async*/) {

	if(current.status==previous.status){
		return;
	}
	var utils=new AssetLoanUtils();

	if(current.status=="approved" && !utils.isAssetAvailable(current.asset.toString())){
		gs.addErrorMessage('This asset is no longer available and cannot be approved.');
		current.setAbortAction(true);
		return;
	}
	//get the asset record
	var assetRecord=new GlideRecord('x_2228927_asset_0_asset');
	if(!assetRecord.get(current.asset)){
		gs.error('Asset Loan Tracker: Could not find asset for loan request ' + current.number);
        return;
	}
	if(current.status=="on_loan" || current.status=="approved"){
		assetRecord.status="on_loan";
		assetRecord.assigned_to=current.requested_by;
		assetRecord.update();

	}else if(current.status=="returned"){
		assetRecord.status = 'available';
        assetRecord.assigned_to = '';
        assetRecord.update();

	}

})(current, previous);
